package cn.binbin.crm;
import java.time.LocalDate;import java.util.UUID;import jakarta.servlet.http.HttpServletRequest;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/analytics")
public class AnalyticsController {
    private final AuthService auth;private final AnalyticsService analytics;
    public AnalyticsController(AuthService auth,AnalyticsService analytics){this.auth=auth;this.analytics=analytics;}
    private AnalyticsService.Filter filter(LocalDate from,LocalDate to,UUID owner,UUID department,String region,String industry){return new AnalyticsService.Filter(from,to,owner,department,region,industry);}
    @GetMapping public Object dashboard(@RequestParam LocalDate from,@RequestParam LocalDate to,@RequestParam(required=false) UUID owner,@RequestParam(required=false) UUID department,@RequestParam(defaultValue="") String region,@RequestParam(defaultValue="") String industry,HttpServletRequest r){return analytics.dashboard(auth.workspace(r),filter(from,to,owner,department,region,industry));}
    @GetMapping("/{module}/details") public Object details(@PathVariable String module,@RequestParam LocalDate from,@RequestParam LocalDate to,@RequestParam(required=false) UUID owner,@RequestParam(required=false) UUID department,@RequestParam(defaultValue="") String region,@RequestParam(defaultValue="") String industry,@RequestParam(defaultValue="") String dimension,@RequestParam(defaultValue="") String value,@RequestParam(defaultValue="1") int page,@RequestParam(defaultValue="20") int pageSize,HttpServletRequest r){return analytics.detail(auth.workspace(r),filter(from,to,owner,department,region,industry),module,dimension,value,page,pageSize);}
    @GetMapping("/{module}/export") public Object export(@PathVariable String module,@RequestParam LocalDate from,@RequestParam LocalDate to,@RequestParam(required=false) UUID owner,@RequestParam(required=false) UUID department,@RequestParam(defaultValue="") String region,@RequestParam(defaultValue="") String industry,@RequestParam(defaultValue="") String dimension,@RequestParam(defaultValue="") String value,HttpServletRequest r){return ResponseEntity.ok().contentType(MediaType.parseMediaType("text/csv;charset=UTF-8")).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=crm-analytics.csv").body(analytics.export(auth.workspace(r),filter(from,to,owner,department,region,industry),module,dimension,value,RequestSafety.trace(r)));}
}
